import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_edges = []
    total_cost = 0
    edges.sort(key=lambda x: x[2])
    for u, v, weight in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_edges.append((u, v, weight))
            total_cost += weight
    return mst_edges

def max_energy_for_non_mst_edges(n, m, edges):
    mst_edges = kruskal(n, edges)
    non_mst_edges = set(edges) - set(mst_edges)
    non_mst_edges = sorted(list(non_mst_edges), key=lambda x: x[2], reverse=True)
    parent = list(range(n + 1))
    rank = [0 for _ in range(n + 1)]
    for u, v, _ in mst_edges:
        union(parent, rank, u, v)
    results = {}
    for u, v, weight in mst_edges:
        max_weight = 0
        for nu, nv, nweight in non_mst_edges:
            if find(parent, nu) != find(parent, nv):
                if nweight <= weight:
                    break
                max_weight = max(max_weight, nweight)
                union(parent, rank, nu, nv)
        results[(u, v)] = max_weight
        union(parent, rank, u, v)
    output = []
    for u, v, weight in non_mst_edges:
        if (u, v) in results:
            output.append(results[(u, v)])
        else:
            output.append(results[(v, u)])
    return output

